gu0(){return"\u0627\u0633\u062a\u063a\u0641\u0631\u0627\u0644\u0644\u0647"},
guy(){return"\u0633\u0641\u0627\u0631\u0634\u06cc"},
gJ8(){return"\u0630\u06a9\u0631 \u0642\u0628\u0644\u06cc"},
gHt(){return"\u0630\u06a9\u0631 \u0628\u0639\u062f\u06cc"},
gLF(){return"\u0632\u06a9\u0627\u062a \u0645\u0627\u0644"},
gJc(){return"\u067e\u0627\u06a9 \u06a9\u0631\u062f\u0646 \u0645\u0627\u0644 \u0648 \u0627\u0641\u0632\u0627\u06cc\u0634 \u0628\u0631\u06a9\u062a \u0622\u0646."},
