gx_(){return"\u0637\u0644\u0627"},
gHw(){return"\u062d\u062f \u0646\u0635\u0627\u0628 \u0632\u06a9\u0627\u062a"},
gLE(){return"\u0627\u0645\u0648\u0627\u0644 \u0634\u0645\u0627"},
