gGE(){return"\u0648\u0627\u0645\u200c\u0647\u0627\u060c \u06a9\u0627\u0631\u062a\u200c\u0647\u0627\u06cc \u0627\u0639\u062a\u0628\u0627\u0631\u06cc \u0648 \u067e\u0631\u062f\u0627\u062e\u062a\u200c\u0647\u0627\u06cc \u0645\u0639\u0648\u0642\u0647\u200c\u0627\u06cc \u06a9\u0647 \u0628\u0627\u06cc\u062f \u062a\u0633\u0648\u06cc\u0647 \u06a9\u0646\u06cc\u062f"},
gHq(){return"\u062e\u0627\u0644\u0635 \u0627\u0645\u0648\u0627\u0644 \u0645\u0634\u0645\u0648\u0644 \u0632\u06a9\u0627\u062a"},
